## Why This Is Asked
Streaming data often requires maintaining a running statistic under insertions and deletions. The median is robust and a common interview target for dynamic data structures.

## Key Concepts
- Two-heap approach: keep lower half in a max-heap and upper half in a min-heap.
- Duplicates supported; lazy deletion via a delay map.
- Rebalancing invariant: size difference at most 1; median derived from heap tops.

## Code Example
```javascript
class MedianDS {
  constructor(){
    this.lo = new MaxHeap(); // lower half
    this.hi = new MinHeap(); // upper half
    this.delayed = new Map();
    this.sizeLo = 0;
    this.sizeHi = 0;
  }
  _cleanTop(h) {
    const top = h.peek();
    while (top !== null && this.delayed.get(top) > 0) {
      h.pop();
      this.delayed.set(top, this.delayed.get(top) - 1);
    }
  }
  add(x){
    if (this.sizeLo === 0 || x <= this.lo.peek()) {
      this.lo.push(x); this.sizeLo++;
    } else { this.hi.push(x); this.sizeHi++; }
    this._balance();
  }
  remove(x){
    const loTop = this.lo.peek();
    if (loTop !== null && x <= loTop) {
      this.delayed.set(x, (this.delayed.get(x) || 0) + 1);
      this.sizeLo--;
      if (x === loTop) this._cleanTop(this.lo);
    } else {
      this.delayed.set(x, (this.delayed.get(x) || 0) + 1);
      this.sizeHi--;
      this._cleanTop(this.hi);
    }
    this._balance();
  }
  _balance(){
    if (this.sizeLo > this.sizeHi + 1) {
      this.hi.push(this.lo.pop()); this.sizeLo--; this.sizeHi++;
    } else if (this.sizeHi > this.sizeLo) {
      this.lo.push(this.hi.pop()); this.sizeHi--; this.sizeLo++;
    }
    this._cleanTop(this.lo); this._cleanTop(this.hi);
  }
  getMedian(){
    if (this.sizeLo === 0) return null;
    if (this.sizeLo > this.sizeHi) return this.lo.peek();
    return (this.lo.peek() + this.hi.peek()) / 2;
  }
}
```

## Why This Is Asked
Tests knowledge of a prefix-based data structure with duplicates and two complementary operations: prefix aggregation and k-th element selection within a constrained subtree.

## Key Concepts
- Trie augmented with passCount and endCount per node
- Duplicate handling via endCount
- Prefix-range query via passCount at prefix node
- K-th retrieval via lexicographic traversal using child passCounts

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.pass = 0;
    this.end = 0;
  }
}
class TrieDict {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let p = this.root; p.pass++;
    for (const ch of word) {
      if (!p.children.has(ch)) p.children.set(ch, new TrieNode());
      p = p.children.get(ch); p.pass++;
    }
    p.end++;
  }
  erase(word) {
    if (!this._exists(word)) return;
    let p = this.root; p.pass--;
    for (const ch of word) {
      const nxt = p.children.get(ch); nxt.pass--;
      if (nxt.pass === 0) p.children.delete(ch); else p = nxt;
    }
    p.end--;
  }
  countWithPrefix(prefix) {
    const node = this._getNode(prefix); return node ? node.pass : 0;
  }
  kthWordWithPrefix(prefix, k) {
    const node = this._getNode(prefix); if (!node) return null;
    let res = prefix; let cur = node;
    // If k falls on words exactly equal to prefix
    if (cur.end >= k) return res;
    k -= cur.end;
    while (true) {
      const keys = Array.from(cur.children.keys()).sort();
      for (const c of keys) {
        const child = cur.children.get(c);
        if (child.pass >= k) { res += c; cur = child; if (cur.end >= k) return res; k -= cur.end; break; }
        k -= child.pass;
      } else { return null; }
    }
  }
  _getNode(s) {
    let p = this.root; for (const ch of s) { if (!p.children.has(ch)) return null; p = p.children.get(ch); } return p;
  }
  _exists(word) { const n = this._getNode(word); return !!n && n.end > 0; }
}
```

